int n,a[100000],dp[100000];
int f(int x){
    if(x>=n)return 0;
    if(dp[x]!=-1)return dp[x];
    int ret=0;
    if(x+1<n){
        if(a[x]<a[x+1])ret=max(ret,f(x+1));
    }
    ret=max(ret,1-f(x+1));
    return dp[x]=ret;
}
